def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 3 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[2:] + filtered_rows[:2]

    group_map = {}
    for row in rotated_rows:
        group, score, timestamp, name = row
        if group not in group_map:
            group_map[group] = (score, timestamp, name)
        else:
            current_score, current_timestamp, current_name = group_map[group]
            if score > current_score:
                group_map[group] = (score, timestamp, name)
            elif score == current_score and timestamp < current_timestamp:
                group_map[group] = (score, timestamp, name)
            elif score == current_score and timestamp == current_timestamp and name > current_name:
                group_map[group] = (score, timestamp, name)

    result = []
    for group in sorted(group_map.keys()):
        score, timestamp, name = group_map[group]
        result.append([group, name])

    return result

